/* Spotify Theme - Official Spotify brand colors */

/* Light mode */
[data-theme="spotify-light"] {
  --background: #ffffff;
  --foreground: #110c0c;
  --card: #faf8f8;
  --card-foreground: #110c0c;
  --popover: #ffffff;
  --popover-foreground: #110c0c;
  --primary: #00a855;
  --primary-foreground: #ffffff;
  --secondary: #ebf0ec;
  --secondary-foreground: #1a1414;
  --muted: #f4f1f2;
  --muted-foreground: #686163;
  --accent: #00c55b;
  --accent-foreground: #110c0c;
  --destructive: #d40924;
  --destructive-foreground: #ffffff;
  --border: #e0ddde;
  --input: #e6e4e4;
  --ring: #00a855;
  --chart-1: #00a855;
  --chart-2: #00c55b;
  --chart-3: #009298;
  --chart-4: #9095e8;
  --chart-5: #d35bb1;
  --radius: 0.5rem;
  --sidebar: #110c0c;
  --sidebar-foreground: #f0eeee;
  --sidebar-primary: #00a855;
  --sidebar-primary-foreground: #ffffff;
  --sidebar-accent: #26201f;
  --sidebar-accent-foreground: #f0eeee;
  --sidebar-border: #2e2726;
  --sidebar-ring: #00a855;
  --font-sans: Montserrat, ui-sans-serif, system-ui, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, SFMono-Regular, monospace;
  --shadow-color: #0a291a;
  --shadow-opacity: 0.08;
  --shadow-blur: 4px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 2px;
  --letter-spacing: -0.01em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 2px 0px hsl(150 60% 10% / 0.04);
  --shadow-xs: 0 1px 3px 0px hsl(150 60% 10% / 0.06);
  --shadow-sm: 0 2px 4px 0px hsl(150 60% 10% / 0.08), 0 1px 2px -1px hsl(150 60% 10% / 0.08);
  --shadow: 0 2px 4px 0px hsl(150 60% 10% / 0.08), 0 1px 2px -1px hsl(150 60% 10% / 0.08);
  --shadow-md: 0 4px 6px 0px hsl(150 60% 10% / 0.1), 0 2px 4px -1px hsl(150 60% 10% / 0.1);
  --shadow-lg: 0 8px 10px 0px hsl(150 60% 10% / 0.1), 0 4px 6px -1px hsl(150 60% 10% / 0.1);
  --shadow-xl: 0 16px 20px 0px hsl(150 60% 10% / 0.12), 0 8px 10px -1px hsl(150 60% 10% / 0.12);
  --shadow-2xl: 0 24px 48px 0px hsl(150 60% 10% / 0.2);
  --tracking-normal: -0.01em;
}

/* Dark mode - #121212 is Spotify's signature dark background */
[data-theme="spotify-dark"] {
  --background: #0a0a0a;
  --foreground: #ffffff;
  --card: #121212;
  --card-foreground: #ffffff;
  --popover: #161616;
  --popover-foreground: #ffffff;
  --primary: #00a855;
  --primary-foreground: #0a0a0a;
  --secondary: #1b1b1b;
  --secondary-foreground: #dedede;
  --muted: #161616;
  --muted-foreground: #8f8f8f;
  --accent: #00c55b;
  --accent-foreground: #0a0a0a;
  --destructive: #de3b3d;
  --destructive-foreground: #ffffff;
  --border: #292929;
  --input: #1b1b1b;
  --ring: #00a855;
  --chart-1: #00a855;
  --chart-2: #00c55b;
  --chart-3: #00a3aa;
  --chart-4: #9fa5f9;
  --chart-5: #de73bd;
  --radius: 0.5rem;
  --sidebar: #060606;
  --sidebar-foreground: #ffffff;
  --sidebar-primary: #00a855;
  --sidebar-primary-foreground: #0a0a0a;
  --sidebar-accent: #1b1b1b;
  --sidebar-accent-foreground: #dedede;
  --sidebar-border: #292929;
  --sidebar-ring: #00a855;
  --font-sans: Montserrat, ui-sans-serif, system-ui, sans-serif;
  --font-serif: ui-serif, Georgia, serif;
  --font-mono: ui-monospace, SFMono-Regular, monospace;
  --shadow-color: #000000;
  --shadow-opacity: 0.5;
  --shadow-blur: 4px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 2px;
  --letter-spacing: -0.01em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 2px 0px hsl(0 0% 0% / 0.25);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.35);
  --shadow-sm: 0 2px 4px 0px hsl(0 0% 0% / 0.5), 0 1px 2px -1px hsl(0 0% 0% / 0.5);
  --shadow: 0 2px 4px 0px hsl(0 0% 0% / 0.5), 0 1px 2px -1px hsl(0 0% 0% / 0.5);
  --shadow-md: 0 4px 6px 0px hsl(0 0% 0% / 0.5), 0 2px 4px -1px hsl(0 0% 0% / 0.5);
  --shadow-lg: 0 8px 10px 0px hsl(0 0% 0% / 0.5), 0 4px 6px -1px hsl(0 0% 0% / 0.5);
  --shadow-xl: 0 16px 20px 0px hsl(0 0% 0% / 0.5), 0 8px 10px -1px hsl(0 0% 0% / 0.5);
  --shadow-2xl: 0 24px 48px 0px hsl(0 0% 0% / 0.6);
}
